draw:
var Rs = p.rs, Rp = p.rp, n = Math.round(p.n);

// exact infinite-ladder value: X is the resistance looking in at a shunt node
var Xinf = (-Rp + Math.sqrt(Rp*Rp + 4*Rp*Rs)) / 2;
var Rinf = Rs + Xinf;

// finite ladder with n sections, built from the far end backwards
var X = Rp;
for (var k = 1; k < n; k++) { X = 1 / (1/Rp + 1/(Rs + X)); }
var Rfin = Rs + X;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.6;
ctx.textAlign = "center";
ctx.textBaseline = "middle";

var top = H * 0.30, bot = H * 0.78;
var left = 34, right = W - 26;
var seg = (right - left) / (n + 0.6);

ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(left, bot); ctx.lineTo(right, bot); ctx.stroke();

function box(x1, y1, x2, y2, label) {
  var mx = (x1+x2)/2, my = (y1+y2)/2;
  var horiz = Math.abs(x2-x1) > Math.abs(y2-y1);
  var w = horiz ? 15 : 8, h = horiz ? 7 : 14;
  ctx.fillStyle = C.paper;
  ctx.fillRect(mx-w, my-h, 2*w, 2*h);
  ctx.strokeStyle = C.rule;
  ctx.strokeRect(mx-w, my-h, 2*w, 2*h);
  ctx.fillStyle = C.ink;
  if (horiz) ctx.fillText(label, mx, my - 16); else ctx.fillText(label, mx + 26, my);
}

var Iin = 1.0;
var Icar = Iin;
for (var i = 0; i < n; i++) {
  var x0 = left + i * seg, x1 = left + (i + 1) * seg;
  ctx.strokeStyle = C.rule;
  ctx.beginPath(); ctx.moveTo(x0, top); ctx.lineTo(x1, top); ctx.stroke();
  box(x0, top, x1, top, Rs.toFixed(1));
  ctx.beginPath(); ctx.moveTo(x1, top); ctx.lineTo(x1, bot); ctx.stroke();
  box(x1, top, x1, bot, Rp.toFixed(1));

  // rest of the ladder beyond this node
  var Xhere = Rp;
  for (var k2 = 1; k2 < n - i; k2++) { Xhere = 1 / (1/Rp + 1/(Rs + Xhere)); }
  var beyond = (i === n - 1) ? Infinity : (Rs + (function () {
    var Z = Rp;
    for (var m = 1; m < n - i - 1; m++) { Z = 1 / (1/Rp + 1/(Rs + Z)); }
    return Z;
  })());
  var fshunt = (beyond === Infinity) ? 1 : beyond / (Rp + beyond);
  var Ishunt = Icar * fshunt;

  ctx.fillStyle = C.figure;
  ctx.fillText(Ishunt.toFixed(3), x1 + 26, (top + bot) / 2 + 20);

  // animated charge sliding along this rung
  var ph = (t * 0.55 + i * 0.17) % 1;
  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(x0 + ph * seg, top, 3, 0, Math.PI*2); ctx.fill();

  Icar = Icar - Ishunt;
}

ctx.fillStyle = C.accent;
ctx.textAlign = "left";
ctx.fillText("1.000 A in", left - 26, top - 26);
ctx.fillStyle = C.figure;
ctx.fillText("shunt currents, in amps, below each rung", left, H - 8);

out.note = n + " section" + (n === 1 ? "" : "s") + ": R = " + Rfin.toFixed(4)
  + " Ω    infinite ladder: R = " + Rinf.toFixed(4) + " Ω";
